public static function order_type( array $grupes ) {
	$n = count( $grupes );
	if ( 0 === $n ) { return 'REVIEW'; }
	if ( 1 === $n ) { return isset( $grupes['av'] ) ? 'MAIN' : 'DS'; }
	return 'MIXED';
}

